// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz the `from` address and a uint value and a single recipient to keep loop simple
    function testFuzz_property(address from, uint256 v, address maybeSame) public {
        // keep tos length exactly 1 so we can reason about single call
        address[] memory tos = new address[](1);
        // fuzzed recipient but avoid zero address to be within normal domain
        tos[0] = maybeSame == address(0) ? address(1) : maybeSame;

        // Deploy a helper that implements only transferFrom(...), not transfer(...)
        // This models a counterparty that will accept the reference's selector but does NOT implement transfer(...)
        OnlyTransferFrom helper = new OnlyTransferFrom();

        // Call through: both reference and mutant return boolean; we observe success vs revert via try/catch
        bool okRef;
        try c.transfer(from, address(helper), tos, v) returns (bool res) {
            okRef = res; // should be true for reference
        } catch {
            okRef = false;
        }

        // The general rule: reference should succeed (okRef == true) for all inputs because helper implements transferFrom selector
        // The mutant that calls transfer(...) will cause the low-level call to the helper to fail (no such function), so mutant would revert and produce ok==false for some inputs.
        // We assert the universal property that reference returns true. The mutant will fail this for some fuzzed inputs (fuzzer finds them).
        assertTrue(okRef);
    }
}

// Helper that exposes exactly the transferFrom selector and records calls; it DOES NOT implement transfer(...)
contract OnlyTransferFrom {
    event TransferFromCalled(address indexed from, address indexed to, uint256 value);

    // function signature matching transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        emit TransferFromCalled(from, to, value);
        return true;
    }

    // no transfer(address,address,uint256) function is declared, so a call to that selector will hit fallback and revert
    fallback() external payable {
        revert("no transfer");
    }

    receive() external payable {
        // accept ether but do nothing
    }
}
